#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    // Usage check: exactly two arguments (program name + two strings)
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    const char *s1 = argv[1];
    const char *s2 = argv[2];

    // Length limit: strings must be shorter than 1025 characters (i.e., max 1024)
    if (strlen(s1) >= 1025 || strlen(s2) >= 1025) {
        puts("TOO_LONG");
        return 0;
    }

    // Count characters case‑insensitively, ignoring spaces.
    int cnt1[256] = {0};
    int cnt2[256] = {0};

    for (const unsigned char *p = (const unsigned char *)s1; *p; ++p) {
        if (*p == ' ') continue;               // ignore spaces
        unsigned char c = *p;
        if (c >= 'A' && c <= 'Z') c += 0x20;   // convert to lower case
        cnt1[c]++;
    }

    for (const unsigned char *p = (const unsigned char *)s2; *p; ++p) {
        if (*p == ' ') continue;               // ignore spaces
        unsigned char c = *p;
        if (c >= 'A' && c <= 'Z') c += 0x20;   // convert to lower case
        cnt2[c]++;
    }

    // Compare the frequency tables.
    int anagram = 1;
    for (int i = 0; i < 256; ++i) {
        if (cnt1[i] != cnt2[i]) {
            anagram = 0;
            break;
        }
    }

    puts(anagram ? "ANAGRAM" : "NOT_ANAGRAM");
    return 0;
}
